<template>
  <SafetyManagementShell title="台账打印预览" subtitle="主表摘要及完整证据附件 · 待签认">
    <view class="sm-card sm-no-print sm-actions"><button class="sm-btn" :disabled="loading || !!error" @click="print">打印 / 保存 PDF</button><button class="sm-btn sm-btn--secondary" :disabled="loading" @click="load">刷新已保存材料</button><text class="sm-help">打印包括主表与完整明细附件。页面中未保存的编辑不包含在本材料中。</text></view>
    <view v-if="loading" class="sm-state">正在准备完整台账和照片证据…</view><view v-else-if="error" class="sm-alert sm-alert--error">{{ error }}</view>
    <!-- #ifdef H5 -->
    <article v-else class="sm-print">
      <h1>{{ title }}</h1><p class="print-company">{{ snapshot.station_name || '无极县新拓能源开发有限公司' }}</p>
      <div class="sm-print-status">{{ stateLabel }} · 签认状态：待签认 · 版本 {{ record?.revision || '未形成核对版本' }}<br />{{ record?.revision_reason ? `修订说明：${record.revision_reason}` : '' }}<br v-if="record?.revision_reason" />生成时间：{{ formatDateTime(bundle.generated_at) }}（北京时间）</div>
      <template v-if="kind==='daily'">
        <p>检查日期：{{ snapshot.date }}　天气：{{ weatherSummary }}　巡查人员：{{ inspectorSummary }}</p>
        <table><thead><tr><th style="width:22%">巡检原单</th><th>各次实际巡查时段（北京时间）</th><th style="width:20%">巡查人 / 天气</th></tr></thead><tbody><tr v-for="inspection in snapshot.inspections" :key="inspection._id"><td>{{ inspection.inspection_no }}</td><td>{{ formatDateTime(inspection.started_at) }} 至 {{ formatDateTime(inspection.ended_at) }}<br />系统提交：{{ formatDateTime(inspection.submitted_at || inspection.created_at) }}</td><td>{{ inspection.inspector_name }}<br />{{ inspection.weather || '未记录' }}</td></tr></tbody></table>
        <h2>一、日检查主表</h2>
        <table><thead><tr><th style="width:13%">类别</th><th style="width:32%">检查内容及标准</th><th>问题描述 / 隐患等级</th><th style="width:23%">当场整改与备注</th></tr></thead><tbody><tr v-for="category in snapshot.categories" :key="category.id"><td>{{ category.id }}．{{ category.name }}</td><td>{{ categorySummary(category) }}</td><td>{{ categoryProblems(category) }}</td><td>{{ categoryOnsite(category) }}</td></tr></tbody></table>
        <h2>二、上报、整改及待办隐患</h2>
        <p v-if="!allHazards.length">当前已保存资料未列出隐患。零报告结论以下方实际确认情况为准。</p>
        <section v-for="issue in allHazards" :key="issue._id"><h3>{{ issue.hazard_no || issue._id }} · {{ issue.hazard_level==='major'?'重大':'一般' }}隐患 · {{ issue.as_of_date ? `截至 ${issue.as_of_date}：` : '' }}{{ issueStatus(issue.status) }}<template v-if="issue.current_status"> · 当前：{{ issueStatus(issue.current_status) }}</template><template v-if="issue.closure_time_unverified"> · 关闭时间证据待核验</template></h3><p>{{ issue.issue_note }}</p><p>责任人：{{ issue.responsible_name || '未填写' }}　期限：{{ issue.planned_complete_date || '未填写' }}<br />整改要求：{{ issue.planned_measure || '未填写' }}<br />实际整改：{{ issue.rectification_note || '未记录' }}<br />复查销号：{{ issue.verification_note || '未记录' }} {{ formatDateTime(issue.verified_at) }}<br />实际上报：{{ reportText(issue.report) }}<br />当场整改：{{ onsiteText(issue.on_site_rectification) }}</p><p v-for="(observation,index) in issueObservations(issue._id)" :key="index">本次观察：{{ observation.issue_note || observation.note }}；{{ formatDateTime(observation.discovered_at || observation.observed_at) }}<br />临时管控：{{ observation.temporary_controls || '未记录' }}<br />实际上报：{{ reportText(observation.report) }}<br />当场整改：{{ onsiteText(observation.on_site_rectification) }}</p></section>
        <h2>三、零报告与核对状态</h2><p>零报告：{{ record?.zero_report?(documentData.stale?'旧版曾确认零报告，当前来源变化后待重新核对':'已按已保存检查事实确认零报告'):'未确认零报告' }}<br />内容核对：{{ record?.checked_at?formatDateTime(record.checked_at):'尚未核对' }}{{ documentData.stale?'；来源已变化，待重新核对':'' }}</p><p v-if="snapshot.missing?.length">尚未完成：<br />{{ snapshot.missing.join('\n') }}</p>
        <table class="print-signatures"><tbody><tr><td>巡查人签字：待签认</td><td>安全总监审阅：待签认</td></tr></tbody></table>
        <section class="print-annex"><h2>附件一：完整检查事实与证据</h2><template v-for="category in snapshot.categories" :key="category.id"><h3>{{ category.id }}．{{ category.name }}</h3><section v-for="(check,index) in category.checks || []" :key="`${check.source_id}-${check.item_code}-${index}`" class="print-check"><p><strong>{{ check.label }}</strong><br />结果：{{ resultLabels[check.result_code] || '待完成' }}<br />来源：{{ check.source_type }} / {{ check.source_id }} / {{ check.item_code }}<br />{{ check.note || '' }}<br v-if="check.note" /><span v-if="check.hazard_ids?.length">关联隐患：{{ check.hazard_ids.join('、') }}</span></p><p v-for="(evidence,i) in check.evidence || []" :key="i">证据：{{ evidence.label || evidence.type }} · {{ evidence.value }}</p><p v-if="check.standard">检查标准：{{ check.standard }}</p><p v-if="check.reason">未开展 / 不适用原因：{{ check.reason }}</p><p v-if="check.details">{{ detailText(check.details) }}</p></section></template></section>
      </template>
      <template v-else>
        <p>统计周期：{{ documentData.period?.start_date }} 至 {{ documentData.period?.end_date }}<br />统计截止日：{{ statistics.as_of_date || documentData.period?.end_date }}；历史待办按截止日状态列示，当前状态另列。<br />实际{{ kind==='weekly'?'排查':'会议' }}日期：{{ content.actual_date || '待填写' }}<br />实际时段：{{ formatDateTime(content.started_at) }} 至 {{ formatDateTime(content.ended_at) }}</p>
        <table><tbody><tr><th>应检天数</th><td>{{ statistics.expected_days ?? '待核对' }}</td><th>实际巡检天数</th><td>{{ statistics.inspected_days ?? '待核对' }}</td></tr><tr><th>已核对日表</th><td>{{ statistics.checked_days ?? '待核对' }}</td><th>新增隐患</th><td>{{ statistics.new_hazard_count ?? '待核对' }}</td></tr><tr><th>已复查销号</th><td>{{ statistics.verified_closed_count ?? '待核对' }}</td><th>整改完成率</th><td>{{ statistics.rectification_rate_label || '待核对' }}</td></tr></tbody></table>
        <template v-if="kind==='monthly'"><h2>关联周排查报告来源</h2><table><thead><tr><th>完整统计周</th><th>实际排查日期 / 组织人</th><th>版本 / 保存状态</th><th>原报告编号</th></tr></thead><tbody><tr v-for="weekly in statistics.weekly_reports || []" :key="weekly._id"><td>{{ weekly.period?.start_date }} 至 {{ weekly.period?.end_date }}</td><td>{{ weekly.content?.actual_date || '待填写' }}<br />{{ weekly.content?.organizer || '待填写' }}</td><td>{{ weekly.revision }} · {{ weekly.content_status==='complete'?'内容完整':'草稿 / 待完善' }} · 待签认</td><td>{{ weekly._id }}</td></tr></tbody></table><p v-if="!statistics.weekly_reports?.length">尚无本月关联的已保存周报告，不能认定已开展周排查。</p></template>
        <section v-for="field in reportFields" :key="field.key"><h2>{{ field.label }}</h2><p>{{ content[field.key] || '待填写' }}</p></section>
        <template v-if="kind==='weekly'"><h2>管理问题与改进措施</h2><table><thead><tr><th>类型 / 问题</th><th>问题风险等级</th><th>措施</th><th>责任人 / 期限</th></tr></thead><tbody><tr v-for="(issue,index) in content.management_issues || []" :key="index"><td>{{ issue.type }}<br />{{ issue.description }}</td><td>{{ riskLabel(issue.risk_level) }}</td><td>{{ issue.measure }}</td><td>{{ issue.responsible_name }}<br />{{ issue.due_date }}</td></tr></tbody></table><p>安全总监签字：待签认　主要负责人审阅：待签认</p></template>
        <template v-else><h2>会议决议与落实</h2><table><thead><tr><th>事项</th><th>责任部门 / 人员</th><th>期限 / 状态</th><th>落实情况</th></tr></thead><tbody><tr v-for="(decision,index) in content.decisions || []" :key="index"><td>{{ decision.subject }}</td><td>{{ decision.department }}<br />{{ decision.responsible_name }}</td><td>{{ decision.due_date }}<br />{{ decisionStatus(decision.status) }}</td><td>{{ decision.implementation || '待落实' }}</td></tr></tbody></table><p>主要负责人签字：待签认　其他参会人员签字：待签认</p></template>
        <section class="print-annex"><h2>附件：日表及隐患统计来源</h2><table><thead><tr><th>日期</th><th>巡检次数</th><th>日表状态</th><th>问题数</th></tr></thead><tbody><tr v-for="day in statistics.daily || []" :key="day.date"><td>{{ day.date }}</td><td>{{ day.inspection_count }}</td><td>{{ dailyStatus(day.status) }}</td><td>{{ day.issue_count }}</td></tr></tbody></table><template v-for="group in hazardGroups" :key="group.key"><h3>{{ group.label }}</h3><p v-for="(issue,index) in statistics[group.key] || []" :key="issue._id || index">{{ issue.hazard_no || issue.hazard_id || issue._id }} · {{ issue.issue_note || issue.note }}<br />责任人：{{ issue.responsible_name || '见原隐患记录' }}　期限：{{ issue.planned_complete_date || '见原隐患记录' }}<br v-if="issue.status" /><template v-if="issue.status">{{ issue.as_of_date ? `截至 ${issue.as_of_date}` : '记录状态' }}：{{ issueStatus(issue.status) }}</template><template v-if="issue.current_status"> · 当前：{{ issueStatus(issue.current_status) }}</template><template v-if="issue.closure_time_unverified"> · 关闭时间证据待核验</template></p><p v-if="!statistics[group.key]?.length">无此类记录</p></template></section>
      </template>
      <section v-if="kind!=='daily' && periodHazards.length" class="print-annex"><h2>完整隐患与整改明细</h2><section v-for="issue in periodHazards" :key="issue._id"><h3>{{ issue.hazard_no || issue._id }} · {{ issue.hazard_level==='major'?'重大':'一般' }}隐患 · {{ issue.as_of_date ? `截至 ${issue.as_of_date}：` : '' }}{{ issueStatus(issue.status) }}<template v-if="issue.current_status"> · 当前：{{ issueStatus(issue.current_status) }}</template><template v-if="issue.closure_time_unverified"> · 关闭时间证据待核验</template></h3><p>{{ issue.issue_note }}<br />首次发现：{{ issue.first_discovered_date || issue.inspection_date }}<br />责任人：{{ issue.responsible_name }} · 期限：{{ issue.planned_complete_date }}<br />整改要求：{{ issue.planned_measure }}<br />实际上报：{{ reportText(issue.report) }}<br />当场整改：{{ onsiteText(issue.on_site_rectification) }}<br />实际整改：{{ issue.rectification_note || '未记录' }}；{{ formatDateTime(issue.rectified_at) }}<br />复查销号：{{ issue.verification_note || '未记录' }}；{{ formatDateTime(issue.verified_at) }}</p><p v-for="(observation,index) in issue.observations || []" :key="index">观察：{{ formatDateTime(observation.observed_at) }} · {{ observation.issue_note }}<br />临时管控：{{ observation.temporary_controls || '未记录' }}<br />上报：{{ reportText(observation.report) }}<br />当场整改：{{ onsiteText(observation.on_site_rectification) }}</p></section></section>
      <section v-if="evidenceFiles.length" class="print-annex"><h2>照片与附件证据清单</h2><p>同一云文件按文件编号仅列一次，保留全部引用来源。责任人原签名不用于本台账三类人员签认。</p><figure v-for="(file,index) in evidenceFiles" :key="file.id" class="print-evidence"><img v-if="file.isImage && file.url" :src="file.url" :alt="`证据 ${index+1}`" @error="photoFailed(file.url)" /><p v-else-if="!file.url">证据链接未取得，需重新加载：{{ file.id }}</p><p v-else>文件附件：{{ file.id }}</p><figcaption>证据 {{ index+1 }} · {{ file.sources.join('；') }}<br />{{ file.id }}</figcaption></figure></section>
      <p class="print-footer">本材料根据已保存巡检、补充和整改资料形成。签认方式尚未确定，本版本保持待签认。</p>
    </article>
    <!-- #endif -->
    <!-- #ifndef H5 -->
    <view class="sm-alert sm-alert--info">请使用网页端打开相同日期的台账打印预览，打印或保存 PDF。Excel 可在台账页面导出。</view>
    <!-- #endif -->
    <view v-if="missingEvidence.length" class="sm-alert sm-alert--error sm-no-print">{{ missingEvidence.length }} 份证据未取得可用链接，暂不能打印。请刷新材料后重试。</view>
    <view v-if="failedPhotos.length" class="sm-alert sm-alert--error sm-no-print">{{ failedPhotos.length }} 张照片未加载，请刷新材料后重试；为避免证据遗漏，照片未加载时不能打印。</view>
  </SafetyManagementShell>
</template>
<script setup>
import { computed,onMounted,ref,watch,nextTick } from 'vue'
import SafetyManagementShell from './SafetyManagementShell.vue'
import { exportSafetyDocument } from '@/services/safetyManagement'
import { beijingDate,formatDateTime,resultLabels,showError } from './helpers'
const props=defineProps({kind:{type:String,default:'daily'},date:{type:String,default:''},month:{type:String,default:''}})
const loading=ref(true),error=ref(''),bundle=ref({}),failedPhotos=ref([])
const documentData=computed(()=>bundle.value.document || {}),snapshot=computed(()=>documentData.value.snapshot || {}),record=computed(()=>documentData.value.record || null),content=computed(()=>record.value?.content || {}),statistics=computed(()=>documentData.value.statistics || {})
const title=computed(()=>({daily:'每日安全生产检查记录表',weekly:'每周安全生产排查报告',monthly:'每月安全生产工作调度会议纪要'})[props.kind])
const stateLabel=computed(()=>documentData.value.stale?'来源变化，待重新核对':props.kind==='daily'?(snapshot.value.complete?(record.value?'内容已核对':'内容齐全，尚未核对'):'内容未完成'):(record.value?.content_status==='complete'?'内容完整':'内容未完成'))
const weatherSummary=computed(()=>[...new Set((snapshot.value.inspections || []).map(item=>item.weather || '未记录'))].join('、') || '未记录'),inspectorSummary=computed(()=>[...new Set((snapshot.value.inspections || []).map(item=>item.inspector_name))].filter(Boolean).join('、') || '未记录')
const allHazards=computed(()=>[...new Map([...(snapshot.value.issues || []),...(snapshot.value.historical_pending || [])].map(item=>[item._id,item])).values()])
const periodHazards=computed(()=>[...new Map(['new_hazards','recurrence','reobserved_hazards','historical_progress','historical_pending'].flatMap(key=>statistics.value[key] || []).map(hazard=>[hazard._id,hazard])).values()])
const hazardGroups=[{key:'new_hazards',label:'本期新发现隐患'},{key:'reobservations',label:'同一问题复见观察'},{key:'recurrence',label:'关闭后复发'},{key:'historical_pending',label:'历史待办'},{key:'historical_progress',label:'历史问题本期处置与销号'}]
const weeklyFields=[['organizer','实际组织人'],['participants','实际参加人员'],['scope','排查范围与依据'],['site_findings','实际现场排查结果'],['execution_evaluation','日管控执行质量评价'],['repeated_problem_analysis','反复问题与原因分析'],['system_gaps','制度漏洞及改进'],['next_plan','下周工作计划']]
const monthlyFields=[['title','会议名称'],['location','会议地点'],['host','主持人'],['recorder','记录人'],['participants','实际参会人员'],['absences','缺席人员及原因'],['previous_decisions','上月决议落实'],['accidents_and_near_misses','事故及涉险情况'],['safety_situation','安全形势及日周工作情况'],['major_risks','重大风险和隐患'],['special_work','专项工作'],['training','教育培训与人员配置'],['expenditure','安全投入保障'],['emergency_management','应急管理'],['contractors','外协管理'],['causes','问题原因分析'],['principal_summary','主要负责人总结']]
const reportFields=computed(()=>(props.kind==='weekly'?weeklyFields:monthlyFields).map(([key,label])=>({key,label})))
const categoryScope={ '1':'检查吊秤、防脱钩状态；核对当日特殊作业、审批、监护和安全措施。', '2':'检查阀门、仪表、报警、防爆及接地等设施；核对设备运行、支撑、检验校验和适用专用装置。', '3':'检查入厂与运瓶行为、劳保纪律、岗位资格和交底；按实际作业核对充装、装卸全过程。', '4':'检查通道、气瓶分区、堆放、照明和通风；按实际作业核对天气与工况。', '5':'检查应急灯、灭火器及消防栓器材状态、取用条件和有效记录。', '6':'检查安全标志、设备标牌、适用气瓶标签与新增变化标志。', '7':'检查应急物资状态；确认内部报告、投诉及历史隐患临时管控落实。' }
function categorySummary(category){const counts={};for(const check of category.checks || []){const label=resultLabels[check.result_code] || '待完成';counts[label]=(counts[label]||0)+1}return `${categoryScope[category.id] || category.name}\n${Object.entries(counts).map(([label,count])=>`${label} ${count} 条`).join('；')}`}
function categoryIssues(category){if(category.issues)return category.issues;const ids=new Set((category.checks || []).flatMap(check=>check.hazard_ids || []));return(snapshot.value.issues || []).filter(issue=>String(issue.category_code)===String(category.id) || ids.has(issue._id))}
function categoryProblems(category){const issues=categoryIssues(category);const parts=issues.map(issue=>`${issue.hazard_no || issue._id}：${issue.issue_note}（${issue.hazard_level==='major'?'重大':'一般'}；${issueStatus(issue.status)}）`);for(const check of category.checks || [])if(check.result_code==='abnormal'&&!check.hazard_ids?.length)parts.push(`${check.label}：${check.note || '异常待描述'}（尚未关联隐患）`);return parts.join('\n') || ((category.checks || []).length && (category.checks || []).every(check=>check.result_code)?'当天已保存材料未登记问题':'待完成检查')}
function issueObservations(id){return(snapshot.value.observations || []).filter(item=>item.hazard_id===id)}
function categoryOnsite(category){const issues=categoryIssues(category),ids=new Set(issues.map(issue=>issue._id));const observations=(snapshot.value.observations || []).filter(item=>ids.has(item.hazard_id));return [...new Set([...issues,...observations].map(item=>onsiteText(item.on_site_rectification)).filter(text=>text!=='未记录当场整改'))].join('\n') || '未记录当场整改；重复引用同一问题不重复计数'}
function detailText(details){return Object.entries({types:'作业类型',location:'地点',approval:'审批',monitor:'监护',measures:'措施'}).filter(([key])=>details[key]).map(([key,label])=>`${label}：${details[key]}`).join('\n')}
const evidenceFiles=computed(()=>{
 const files=new Map();const add=(id,source)=>{if(typeof id!=='string'||!id.startsWith('cloud://'))return;if(!files.has(id))files.set(id,{id,url:bundle.value.media_urls?.[id] || '',isImage:! /\.(pdf|docx?|xlsx?|txt)(?:[?#]|$)/i.test(id),sources:[]});const row=files.get(id);if(!row.sources.includes(source))row.sources.push(source)}
 for(const category of snapshot.value.categories || [])for(const check of category.checks || [])for(const evidence of check.evidence || [])if(evidence.type==='file')add(evidence.value,`${category.name} · ${check.label} · ${check.source_id || '补充记录'}`)
 const walk=(value,source,key='')=>{if(/signature|签名|签字/i.test(key))return;if(typeof value==='string')add(value,source);else if(Array.isArray(value))value.forEach(item=>walk(item,source,key));else if(value && typeof value==='object')for(const [childKey,child] of Object.entries(value)){const label=({rectification_photo_file_ids:'整改照片',verification_photo_file_ids:'复查照片',on_site_rectification:'当场整改',observations:'观察记录',evidence:'证据',photo_file_ids:'现场照片'})[childKey];walk(child,label?`${source} · ${label}`:source,childKey)}}
 if(props.kind==='daily'){for(const issue of allHazards.value)walk(issue,`${issue.hazard_no || issue._id}`);for(const inspection of snapshot.value.inspections || [])for(const item of inspection.items || [])for(const id of item.photo_file_ids || [])add(id,`${inspection.inspection_no} · ${item.item_label_snapshot || item.item_code}`)}else{for(const key of ['new_hazards','reobservations','recurrence','historical_pending','reobserved_hazards','historical_progress'])for(const issue of statistics.value[key] || [])walk(issue,issue.hazard_no || issue.hazard_id || issue._id || '统计证据')}
 return [...files.values()]
})
const missingEvidence=computed(()=>evidenceFiles.value.filter(file=>!file.url))
function reportText(report){return report?.reported_at?`${formatDateTime(report.reported_at)}，${report.reported_to}，${report.method}；要求：${report.requirements || '未另填'}`:'未记录实际上报'}
function onsiteText(onsite){return onsite?.note?`${onsite.note}；${formatDateTime(onsite.completed_at)}；复查：${onsite.recheck_note}，${formatDateTime(onsite.rechecked_at)}`:'未记录当场整改'}
function issueStatus(value){return({pending_rectification:'待整改',pending_verification:'待复查',closed:'已复查销号',cancelled:'已取消'})[value] || value}
function riskLabel(value){return({general:'一般',elevated:'较大',major:'重大'})[value] || '待填写'}
function decisionStatus(value){return({pending:'待落实',in_progress:'落实中',completed:'已完成'})[value] || value}
function dailyStatus(value){return({no_inspection:'无巡检',incomplete:'日表待完成',pending_signature:'待签认',recheck_required:'待重新核对',not_enabled:'未启用'})[value] || value}
function photoFailed(url){if(!failedPhotos.value.includes(url))failedPhotos.value.push(url)}
async function load(){loading.value=true;error.value='';failedPhotos.value=[];try{bundle.value=await exportSafetyDocument({kind:props.kind,...(props.kind==='monthly'?{month:props.month || beijingDate().slice(0,7)}:{date:props.date || beijingDate()}),format:'snapshot'})}catch(err){error.value=err.message}finally{loading.value=false}}
async function print(){uni.hideToast();uni.hideLoading();if(missingEvidence.value.length)return showError(new Error('部分证据未取得可用链接，请刷新后再打印'));if(failedPhotos.value.length)return showError(new Error('有照片加载失败，请刷新后再打印'));await nextTick();
// #ifdef H5
const pending=Array.from(document.querySelectorAll('.sm-print img')).some(image=>!image.complete || !image.naturalWidth);if(pending)return showError(new Error('照片仍在加载，请稍候再打印'));window.print()
// #endif
}
watch(()=>[props.kind,props.date,props.month],load)
onMounted(load)
</script>
<style scoped>
.sm-print { padding:32px; margin-top:24px; border:1px solid #dce5ec; background:white; color:#182635; font-size:14px; line-height:1.7; }.sm-print h1 { font-size:26px; text-align:center; }.print-company { text-align:center; }.sm-print h2 { font-size:19px; margin:24px 0 12px; }.sm-print h3 { font-size:16px; margin:18px 0 8px; }.sm-print table { border-collapse:collapse; width:100%; table-layout:fixed; }.sm-print th,.sm-print td { border:1px solid #94a3b8; padding:10px; vertical-align:top; text-align:left; overflow-wrap:anywhere; white-space:pre-wrap; }.sm-print p { white-space:pre-wrap; overflow-wrap:anywhere; }.sm-print-status { border:1px solid #d6b67c; padding:12px; margin:20px 0; background:#fffaf0; }.print-evidence{display:block;break-inside:avoid;margin:18px 0;padding:12px;border:1px solid #cbd5e1}.print-evidence img{display:block;max-width:100%;max-height:270px;margin:auto;object-fit:contain}.print-evidence figcaption{font-size:11px;overflow-wrap:anywhere}.print-photo { display:inline-block; width:31%; margin:1%; vertical-align:top; }.print-photo img { max-width:100%; max-height:220px; }.print-photo figcaption { font-size:11px; }.print-check { border-bottom:1px solid #dce5ec; padding-bottom:16px; }.print-footer { margin-top:30px; color:#64748b; font-size:12px; }.print-signatures { margin:24px 0; }.print-signatures td { height:56px; }@media(max-width:600px){.sm-print { padding:12px; font-size:12px; }.sm-print h1 { font-size:20px; }.sm-print th,.sm-print td { padding:5px; }.print-photo { width:48%; }}@media print{.sm-print{padding:0;border:0;margin:0;font-size:11pt;color:black}.print-photo{width:31%}.sm-print-status{background:white}.print-check{break-inside:auto}.print-signatures{break-inside:avoid}}
</style>
